import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("renaming a vendor to another vendor's name is refused whatever the case", { tag: "@LIF-10" }, async ({ factory, apiAs }) => {
  // Arrange
  const atlas = await factory.vendor({ as: "member", name: uniqueName("Atlas Freight") });
  const borealis = await factory.vendor({ as: "member", name: uniqueName("Borealis Freight") });
  const member = await apiAs("member");

  // Act: rename Borealis to Atlas's name, in upper case
  const response = await member.patch(`/api/vendors/${borealis.id}`, {
    data: { name: atlas.name.toUpperCase() },
  });

  // Assert: refused with the documented error code
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Assert: the stored name is unchanged
  const stored = await expectStatus(await member.get(`/api/vendors/${borealis.id}`), 200);
  expect(stored.name).toBe(borealis.name);
});
